import * as T from '../vendor/three.module.js';
import {MissileSystem,distanceToBox,segmentHit} from './flight.js?v=9';
import {nearestRoad} from './road-network.js?v=9';
export function createActionMode(scene,world,traffic,car,effects,sound,onEvent){
 let destroyed=0,viewer=null;const zero=new T.Matrix4().makeScale(0,0,0),dummy=new T.Object3D(),wreck=new T.InstancedMesh(new T.BoxGeometry(1,1,1),new T.MeshStandardMaterial({color:'#414346',roughness:1}),240);wreck.frustumCulled=false;wreck.castShadow=true;scene.add(wreck);let wreckCursor=0;for(let i=0;i<240;i++)wreck.setMatrixAt(i,zero);
 const airKit=new T.Group();car.root.add(airKit);const metal=new T.MeshStandardMaterial({color:'#657780',metalness:.7,roughness:.3}),glow=new T.MeshBasicMaterial({color:'#77d7ff',transparent:true,opacity:.8});
 const ailerons=[];for(const side of [-1,1]){const wing=new T.Mesh(new T.BoxGeometry(3.2,.1,1.4),metal);wing.position.set(side*2,.45,.15);wing.rotation.y=side*.17;airKit.add(wing);const aileron=new T.Mesh(new T.BoxGeometry(1.5,.07,.35),metal);aileron.position.set(side*2.7,.45,.95);airKit.add(aileron);ailerons.push(aileron);const tail=new T.Mesh(new T.BoxGeometry(1.4,.07,.65),metal);tail.position.set(side*1,.7,1.95);airKit.add(tail);const engine=new T.Mesh(new T.CylinderGeometry(.23,.26,.85,14),metal);engine.rotation.x=Math.PI/2;engine.position.set(side*.7,.4,2);airKit.add(engine);const flame=new T.Mesh(new T.ConeGeometry(.22,1.5,14),glow);flame.rotation.x=Math.PI/2;flame.position.set(side*.7,.4,3);airKit.add(flame);}const fin=new T.Mesh(new T.BoxGeometry(.09,1.1,.9),metal);fin.position.set(0,1.15,1.85);airKit.add(fin);airKit.visible=false;
 const exhaustMaterial=new T.MeshBasicMaterial({color:'#ff8a21',transparent:true,opacity:.75,blending:T.AdditiveBlending,depthWrite:false}),coreMaterial=new T.MeshBasicMaterial({color:'#fff3bd',transparent:true,opacity:.95,blending:T.AdditiveBlending,depthWrite:false}),tipMaterial=new T.MeshStandardMaterial({color:'#c0c8ca',metalness:.7,roughness:.25});
 const missiles=Array.from({length:6},()=>{const root=new T.Group(),body=new T.Mesh(new T.CylinderGeometry(.09,.11,1.1,10),metal),tip=new T.Mesh(new T.ConeGeometry(.095,.36,10),tipMaterial);tip.position.y=.72;root.add(body,tip);for(let i=0;i<4;i++){const fin=new T.Mesh(new T.BoxGeometry(.035,.4,.38),metal);fin.position.y=-.4;fin.rotation.y=i*Math.PI/2;root.add(fin);}const plume=new T.Mesh(new T.ConeGeometry(.25,2.8,12),exhaustMaterial);plume.rotation.z=Math.PI;plume.position.y=-1.9;const core=new T.Mesh(new T.ConeGeometry(.13,1.35,12),coreMaterial);core.rotation.z=Math.PI;core.position.y=-1.16;root.add(plume,core);root.userData.plume=plume;scene.add(root);root.visible=false;return root;});
 function floor(x,z){const r=nearestRoad(world.roads,x,z);return Math.max(.04,r.y-Math.max(0,r.distance-r.road.widthAt(r.d)/2)/1.5);}
 function destroy(target){if(target.destroyed)return false;target.destroyed=true;target.speed=0;if(target.model)target.model.root.visible=false;for(const {mesh,index}of target.instances||[]){mesh.setMatrixAt(index,zero);mesh.instanceMatrix.needsUpdate=true;}for(const object of target.objects||[])object.visible=false;destroyed++;for(let i=0;i<5;i++){dummy.position.set(target.x+(Math.random()-.5)*(target.hx??.88)*1.5,(target.y||0)+.22,target.z+(Math.random()-.5)*(target.hz??2.2)*1.5);dummy.rotation.set(Math.random()*.3,Math.random()*Math.PI,.2);dummy.scale.set(.4+Math.random()*1.5,.3+Math.random()*.6,.5+Math.random()*1.3);dummy.updateMatrix();wreck.setMatrixAt(wreckCursor++%240,dummy.matrix);}wreck.instanceMatrix.needsUpdate=true;return true;}
 const system=new MissileSystem((hit,target)=>{effects.explode(hit,viewer);sound.explosion(viewer?Math.hypot(viewer.x-hit.x,viewer.y-hit.y,viewer.z-hit.z):25);let count=0;for(const object of [...world.colliders,...traffic.cars])if(!object.destroyed&&(object===target||distanceToBox(hit,object)<7)&&destroy(object))count++;onEvent({type:'explosion',hit,count,message:count?`${count}件を破壊`:'着弾'});});
 const direction=new T.Vector3(),up=new T.Vector3(0,1,0),muzzle=new T.Vector3(),aim=new T.Vector3(),attitude=new T.Euler(0,0,0,'YXZ');let trailTimer=0;
 return {system,get destroyed(){return destroyed;},floor,canLand(state){const r=nearestRoad(world.roads,state.x,state.z);return r.onSurface&&(!r.road.highway||!r.road.hasBarrier(r.d)||(Math.abs(r.side)>1.5&&Math.abs(r.side)<r.road.widthAt(r.d)/2-1.2))&&!world.colliders.some(b=>!b.destroyed&&Math.abs(b.x-state.x)<b.hx+1.2&&Math.abs(b.z-state.z)<b.hz+2.4)&&!traffic.cars.some(c=>!c.destroyed&&Math.hypot(c.x-state.x,c.z-state.z)<5);},
 fire(state,camera){camera.getWorldDirection(direction);const from={x:camera.position.x,y:camera.position.y,z:camera.position.z},end={x:from.x+direction.x*400,y:from.y+direction.y*400,z:from.z+direction.z*400};let fraction=1;for(const target of [...world.colliders,...traffic.cars]){const t=segmentHit(from,end,target);if(t!==null&&t*400>5&&t<fraction)fraction=t;}for(let d=20;d<400*fraction;d+=4){const p={x:from.x+direction.x*d,y:from.y+direction.y*d,z:from.z+direction.z*d};if(p.y<floor(p.x,p.z)){fraction=d/400;break;}}aim.set(from.x+(end.x-from.x)*fraction,from.y+(end.y-from.y)*fraction,from.z+(end.z-from.z)*fraction);attitude.set(state.flight?state.flightPitch:0,state.yaw,state.flight?-state.flightBank:0);muzzle.set((system.shots%2?-.65:.65),.9,-2.8).applyEuler(attitude);const origin={x:state.x+muzzle.x,y:state.y+muzzle.y,z:state.z+muzzle.z};direction.copy(aim).sub(muzzle.set(origin.x,origin.y,origin.z)).normalize();const shot=system.fire(origin,direction);if(shot){sound.launch();effects.launch?.(origin);}return !!shot;},
 update(dt,state){viewer=state;system.step(dt,[...world.colliders,...traffic.cars.filter(c=>!c.destroyed)],floor);trailTimer+=dt;for(let i=0;i<missiles.length;i++){const m=system.items[i],mesh=missiles[i];mesh.visible=!!m;if(m){mesh.position.set(m.x,m.y,m.z);direction.set(m.vx,m.vy,m.vz).normalize();mesh.quaternion.setFromUnitVectors(up,direction);mesh.userData.plume.scale.set(1,1+Math.sin(m.life*75)*.15,1);if(trailTimer>.035)effects.trail(m);}}if(trailTimer>.035)trailTimer=0;airKit.visible=!!state.flight;for(let i=0;i<2;i++)ailerons[i].rotation.x=(i?1:-1)*(state.rollRate||0)*.3;glow.opacity=.7+Math.sin(performance.now()*.02)*.2;effects.update(dt);}
 };
}
